preConditionHook:
// Exit-by-placement (Davey, Entry & Exit Confessions, exit #6): after N
// consecutive rising closes take the long profit; after N falling closes
// cover the short. Reads no position state on purpose -- the streak may
// pre-date the entry. Same loop as MomentumConsecutiveBars at lookback 1.
ConditionOne = true;
ConditionTwo = true;
for (ii = 0; ii < (int)consecutiveBars; ++ii) {
    if (el_le(close[ii], close[ii + 1])) ConditionOne = false;
    if (el_ge(close[ii], close[ii + 1])) ConditionTwo = false;
}
